head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    if (tabControl1.tabArr[0].disabled === false) {
        tabControl1.disableTab(0);
    } else {
        tabControl1.enableTab(0);
    }
};
scwin.trigger3_onclick = function(e) {
    if (tabControl2.tabArr[1].disabled === false) {
        tabControl2.disableTab(1);
    } else {
        tabControl2.enableTab(1);
    }
};
scwin.hasClass = function(id) {
	return WebSquare.wUnit.getJq(id).hasClass('w2tabcontrol_disabled');
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger3').click()");
    WebSquare.wUnit.addCommand("pause", "400");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "400");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "400");
    WebSquare.wUnit.addCommand("assert", "scwin.hasClass('#tabControl2_tab_tabs3')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
